import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Retro — intake round 2: 166 real workloads, 0 shippable laws","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/project/retros/intake-round-2.md","filePath":"vendored/graphopt/project/retros/intake-round-2.md"}`),a={name:`graphopt/project/retros/intake-round-2.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="retro-—-intake-round-2-166-real-workloads-0-shippable-laws" tabindex="-1">Retro — intake round 2: 166 real workloads, 0 shippable laws <a class="header-anchor" href="#retro-—-intake-round-2-166-real-workloads-0-shippable-laws" aria-label="Permalink to “Retro — intake round 2: 166 real workloads, 0 shippable laws”">​</a></h1><p><strong>Status:</strong> landed (<code>python -m mlopt_discovery.intake</code>, <code>torch_bridge.py</code>, <code>attrs.py</code>); pipeline delta is an honest negative.</p><h2 id="what-landed" tabindex="-1">What landed <a class="header-anchor" href="#what-landed" aria-label="Permalink to “What landed”">​</a></h2><p><code>law_intake.py</code> grew a three-class intake: <strong>ingested</strong> (exported + all ops bound + fp64-verified lowered module), <strong>census-only</strong> (exported, missing bindings — the backlog), <strong>rejected</strong> (export boundary raised; exception recorded verbatim). The candidate table now covers ~40 real <code>nn.*</code> spellings nobody hand-wrote: pooling (<code>MaxPool2d</code>, <code>AdaptiveAvgPool2d</code>), <code>Upsample</code> (nearest/bilinear), <code>Unfold</code>/<code>Fold</code>, <code>BatchNorm1d/2d</code>, <code>GroupNorm</code>, <code>LayerNorm</code>, <code>InstanceNorm</code>, <code>LocalResponseNorm</code>, <code>ConvTranspose2d</code>, <code>Conv3d</code>, <code>PixelShuffle</code>, <code>Dropout2d</code>, <code>Embedding</code>, <code>Bilinear</code>, <code>CosineSimilarity</code>, <code>CrossEntropyLoss</code>, <code>MSELoss</code>, RNN/GRU/LSTM families, attention variants, and compound models.</p><h3 id="corpus-growth-vs-post-round-1" tabindex="-1">Corpus growth (vs. post-round-1) <a class="header-anchor" href="#corpus-growth-vs-post-round-1" aria-label="Permalink to “Corpus growth (vs. post-round-1)”">​</a></h3><table tabindex="0"><thead><tr><th>metric</th><th>before</th><th>after</th></tr></thead><tbody><tr><td>workloads</td><td>44 cases</td><td><strong>166</strong></td></tr><tr><td>census terms</td><td>145</td><td><strong>276</strong></td></tr><tr><td>op-tuples</td><td>290</td><td><strong>588</strong></td></tr><tr><td>shapes</td><td>730</td><td><strong>1084</strong></td></tr><tr><td>op nodes</td><td>1167</td><td><strong>1586</strong></td></tr></tbody></table><h3 id="new-binding-lowering-work-torch-bridge-attrs" tabindex="-1">New binding/lowering work (torch_bridge + attrs) <a class="header-anchor" href="#new-binding-lowering-work-torch-bridge-attrs" aria-label="Permalink to “New binding/lowering work (torch_bridge + attrs)”">​</a></h3><ul><li><code>fill_.Tensor</code>/<code>fill_.Scalar</code>/<code>masked_fill_*</code>/<code>zero_</code> — the copy_-family mutation threading (BatchNorm buffer writes, loss masks); <code>_fill_src</code> materialises the scalar write as a term, and drops are honest rejections, not silent mints.</li><li><code>special_gammaln</code> → <code>gammaln</code>; <code>__or__</code>/<code>__and__</code> → the bound bitwise ops.</li><li><strong><code>take_along_dim</code> attr-schema bug</strong> — <code>dim</code> sits at arg-position <strong>2</strong> (the index tensor is position 1), not 1; the schema was name-firing on the wrong operand. Latent defect, real fix.</li></ul><h3 id="outcomes" tabindex="-1">Outcomes <a class="header-anchor" href="#outcomes" aria-label="Permalink to “Outcomes”">​</a></h3><ul><li><strong>114 ingested</strong> (verify fp64-clean), <strong>52 census-only</strong>, <strong>2 rejections</strong>: <code>nn.CTCLoss</code> (known dynamic-output) and <code>nn.GaussianNLLLoss</code> (same family). 0 verify failures — round 1&#39;s three defect classes stayed fixed.</li></ul><h2 id="pipeline-delta-—-the-honest-part" tabindex="-1">Pipeline delta — the honest part <a class="header-anchor" href="#pipeline-delta-—-the-honest-part" aria-label="Permalink to “Pipeline delta — the honest part”">​</a></h2><p>66 candidates proposed, 33 firing on a real model, <strong>0 shippable</strong>.</p><p>The top rankers are <code>mixed:</code>-family view/index identities (<code>add_getitem_l_id</code>, <code>mul_select_l_id</code>, …): most stay <em>unproven</em> (no oracle for the view-manipulation class), several are <em>false</em> (<code>add_select_r_id</code>, <code>mul_transpose_l_id</code>, <code>eq_getitem_l_id</code> — numeric rejects: elementwise×indexed views don&#39;t distribute naively), and the recognizable folds (<code>mul_select</code>, <code>linear_factor</code>, <code>softmax</code>) are already shipped duplicates.</p><p><strong>Read:</strong> the easy laws are mined. A 3× corpus now surfaces view/index identities whose verification needs a <em>different</em> oracle (gather/index semantics, not elementwise numeric equality) rather than more shapes. That — not another intake round — is the next yield gate.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};